use crate::error::{Error, Result};

pub const USAGE: &str = "command-library - pick a command from the library with fzf and print it

Usage:
  command-library --config FILE [--query QUERY] [--expand]

Options:
  --config FILE      Command library JSON generated by Home Manager.
  -q, --query QUERY  Prefill the fzf query.
  --expand           Expand QUERY when it is exactly an alias; otherwise
                     pick from the entries whose tag matches its first word.
  -h, --help         Show this help.

Placeholders such as <name> are filled before the command is printed.";

#[derive(Debug, PartialEq, Eq)]
pub struct Args {
    pub config: String,
    pub query: String,
    pub expand: bool,
}

#[derive(Debug, PartialEq, Eq)]
pub enum Invocation {
    Help,
    Run(Args),
}

pub fn parse_args(argv: impl IntoIterator<Item = String>) -> Result<Invocation> {
    let mut config = None;
    let mut query = String::new();
    let mut expand = false;
    let mut argv = argv.into_iter();
    while let Some(arg) = argv.next() {
        match arg.as_str() {
            "-h" | "--help" => return Ok(Invocation::Help),
            "--config" | "-q" | "--query" => {
                let value = argv
                    .next()
                    .ok_or_else(|| Error::Usage(format!("{arg} requires a value")))?;
                if arg == "--config" {
                    config = Some(value);
                } else {
                    query = value;
                }
            }
            "--expand" => expand = true,
            _ => return Err(Error::Usage(format!("unknown argument: {arg}"))),
        }
    }
    let config = config.ok_or_else(|| Error::Usage("--config is required".to_string()))?;
    Ok(Invocation::Run(Args {
        config,
        query,
        expand,
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(args: &[&str]) -> Result<Invocation> {
        parse_args(args.iter().map(ToString::to_string))
    }

    #[test]
    fn parses_every_option() {
        assert_eq!(
            parse(&["--config", "c.json", "-q", "nix", "--expand"]),
            Ok(Invocation::Run(Args {
                config: "c.json".to_string(),
                query: "nix".to_string(),
                expand: true,
            }))
        );
    }

    #[test]
    fn reports_usage_errors_in_order() {
        assert_eq!(
            parse(&["--bogus", "--help"]),
            Err(Error::Usage("unknown argument: --bogus".to_string()))
        );
        assert_eq!(
            parse(&["--config"]),
            Err(Error::Usage("--config requires a value".to_string()))
        );
        assert_eq!(
            parse(&[]),
            Err(Error::Usage("--config is required".to_string()))
        );
        assert_eq!(parse(&["--help", "--bogus"]), Ok(Invocation::Help));
    }
}
